WITH base AS (SELECT id, reading_ts, temp_c, humidity, pressure, firmware, FLOOR(status_bits) AS status_bits_whole FROM device_readings WHERE pressure < 1025) SELECT id, reading_ts, temp_c, humidity, pressure, firmware, status_bits_whole, LAG(status_bits_whole) OVER w_hist AS prev_status_bits_whole, LEAD(status_bits_whole) OVER w_hist AS next_status_bits_whole, LAG(humidity) OVER w_hist AS prev_humidity, LEAD(humidity) OVER w_hist AS next_humidity, ROW_NUMBER() OVER w_hist AS row_seq, ROW_NUMBER() OVER (ORDER BY pressure DESC, id ASC) AS event_seq FROM base WHERE reading_ts < '2023-07-01' WINDOW w_hist AS (ORDER BY pressure ASC, id ASC)
